"""Select complete native constructor results at the provider intake boundary.

Opt-in graph transformation for the current cached ordinary/paired/logical
provider. One shared intake chooses between two constructor-family helpers,
using the unchanged metadata expression. Geometry, mouth identity lookup and
status packing finish inside each helper. All formula groups and fallbacks
remain shared and unchanged. No fixture identity or solved data is embedded.

Logical-chain selection remains inside the complete logical helper. An optional
internal-separator wrapper remains outside the transformed provider, preserving
all its outputs and operations. Unfamiliar layouts reject explicitly.
"""
import hashlib
import bpy


LABEL = 'Shared logical cluster surface'
PURE_SELECTOR_NODES = {
    'NodeGroupInput', 'ShaderNodeMath', 'FunctionNodeCompare',
    'GeometryNodeAttributeStatistic', 'GeometryNodeSampleIndex',
    'GeometryNodeInputNamedAttribute',
}


def _upstream(start):
    found = set()
    def visit(node):
        if node in found:
            return
        found.add(node)
        for socket in node.inputs:
            for link in socket.links:
                visit(link.from_node)
    visit(start)
    return found


def _selector(owner, source, name):
    keep = _upstream(source.node)
    if any(n.bl_idname not in PURE_SELECTOR_NODES for n in keep):
        raise ValueError('Constructor selection is not the supported metadata-only expression')
    inputs = {l.from_socket.identifier for n in keep for s in n.inputs for l in s.links
              if l.from_node.type == 'GROUP_INPUT'}
    allowed = {'Logical Clusters', 'Cluster Sites', 'Owner Index'}
    used = {s.name for s in owner.interface.items_tree
            if s.item_type == 'SOCKET' and s.in_out == 'INPUT' and s.identifier in inputs}
    if used != allowed:
        raise ValueError(('Unexpected constructor selection inputs', used))
    tree = owner.copy()
    tree.name = name+' / Selection'
    value = next(s for s in tree.nodes[source.node.name].outputs if s.identifier == source.identifier)
    names = {n.name for n in keep}
    for node in list(tree.nodes):
        if node.name not in names:
            tree.nodes.remove(node)
    for socket in list(tree.interface.items_tree):
        if socket.item_type == 'SOCKET' and (socket.in_out == 'OUTPUT' or socket.identifier not in inputs):
            tree.interface.remove(socket)
    tree.interface.new_socket(name='Select Logical', in_out='OUTPUT', socket_type='NodeSocketBool')
    out = tree.nodes.new('NodeGroupOutput')
    tree.links.new(value, out.inputs['Select Logical'])
    return tree


def _bind_arguments(tree, original, copy):
    for socket in copy.inputs:
        binding = original.inputs[socket.identifier]
        if binding.is_linked:
            link, = binding.links
            tree.links.new(link.from_socket, socket)
        elif hasattr(binding, 'default_value'):
            socket.default_value = binding.default_value


def _choices(owner, logical):
    """Find the outer logical/ordinary switches through an optional chain choice."""
    links = [l for l in owner.links if l.from_node == logical]
    if len(links) != 3 or {l.from_socket.name for l in links} != {'Geometry', 'Mouths', 'Status'}:
        raise ValueError('Only three-stream logical dispatch is supported')
    chain_preserved = False
    if all(l.to_socket.name == 'False' for l in links):
        outer = []
        chain_calls = set()
        for link in links:
            switch = link.to_node
            if switch.bl_idname != 'GeometryNodeSwitch' or switch.input_type != 'GEOMETRY':
                raise ValueError('Unknown intermediate logical dispatch')
            chain_link, = switch.inputs['True'].links
            chain_call = chain_link.from_node
            if (chain_call.type != 'GROUP' or chain_call.label != 'Original multi-owner boundary program'
                    or chain_link.from_socket.name != link.from_socket.name):
                raise ValueError('Logical dispatch is not the supported chain choice')
            chain_calls.add(chain_call)
            following, = switch.outputs['Output'].links
            outer.append(following)
        if len(chain_calls) != 1:
            raise ValueError('Logical streams do not share one chain constructor')
        links = outer
        chain_preserved = True
    choices = [l.to_node for l in links]
    if any(l.to_socket.name != 'True' or n.bl_idname != 'GeometryNodeSwitch' or
           n.input_type != 'GEOMETRY' for l, n in zip(links, choices)) or len(set(choices)) != 3:
        raise ValueError('Logical outputs do not enter three independent geometry switches')
    return choices, chain_preserved


